/**
 * The browser side of the ACP agent bridge: the wire the Go side owns, the
 * activation calls, and the WebSocket that carries one conversation.
 *
 * The names below are mirrored from `internal/acpbridge/wire.go`, where the Go
 * constants are the source; a golden fixture generated by the Go tests and asserted
 * here (phase 6) is what keeps the two from drifting, so nothing in this module may
 * rename a field on its own.
 *
 * The bridge is inert until the user activates it: this module never dials by itself,
 * `fetchAgentState` is the only call a panel may make before activation, and the
 * connection is created only by `connectAgent`, which the panel calls when it is
 * opened.
 */

/** Envelope kinds, mirrored from the Go constants. */
export const ENVELOPE_STATE = "state";
export const ENVELOPE_PROMPT = "prompt";
export const ENVELOPE_CANCEL = "cancel";
export const ENVELOPE_PERMISSION = "permission";

/** Message roles. */
export const ROLE_USER = "user";
export const ROLE_ASSISTANT = "assistant";

/** Part kinds: each names the session/update variant that produced it. */
export const PART_TEXT = "text";
export const PART_THOUGHT = "thought";
export const PART_TOOL_CALL = "tool_call";
export const PART_PERMISSION = "permission";

/** The user's answer to a permission card, as the bridge records it. */
export const DECISION_ALLOWED = "allowed";
export const DECISION_DENIED = "denied";

/** Paths of the viewer's agent endpoints. */
export const AGENT_STATE_PATH = "/api/agent/state";
export const AGENT_ACTIVATE_PATH = "/api/agent/activate";
export const AGENT_DEACTIVATE_PATH = "/api/agent/deactivate";
export const AGENT_WS_PATH = "/api/agent/ws";

/** AgentState is what the viewer reports before and after activation. */
export interface AgentState {
  activated: boolean;
  connected: boolean;
  session?: string;
  error?: string;
}

/** Permission is one request waiting for the user. */
export interface AgentPermission {
  requestId: string;
  sessionId: string;
  toolCallId?: string;
  toolKind?: string;
  title?: string;
  input?: unknown;
  /** Set when the answer arrives, so the card resolves in place. */
  decision?: string;
}

/** ToolCall is one tool the agent ran. */
export interface AgentToolCall {
  id: string;
  title?: string;
  kind?: string;
  status?: string;
  input?: unknown;
  output?: unknown;
}

/** Part is one piece of a message. */
export interface AgentPart {
  kind: string;
  text?: string;
  toolCall?: AgentToolCall;
  permission?: AgentPermission;
}

/** Message is one user or assistant turn. */
export interface AgentMessage {
  id: string;
  role: string;
  parts: AgentPart[];
}

/** Plan is the agent's execution plan, whole or as the payload it sent. */
export interface AgentPlan {
  id?: string;
  entries?: { content: string; priority?: string; status?: string }[];
  raw?: unknown;
}

/** AgentThread is the whole state of one session, as the bridge sends it. */
export interface AgentThread {
  sessionId: string;
  messages: AgentMessage[];
  plan?: AgentPlan;
  commands?: { name: string; description?: string }[];
  mode?: string;
  config?: unknown[];
  info?: { title?: string; updatedAt?: string };
  usage?: { used: number; size: number; amount?: number; currency?: string };
}

/** AgentStateEnvelope is one whole-thread state, one JSON message. */
export interface AgentStateEnvelope {
  type: string;
  sessionId: string;
  thread: AgentThread;
}

/** The three commands a browser sends. */
export type AgentCommand =
  | { type: typeof ENVELOPE_PROMPT; text: string }
  | { type: typeof ENVELOPE_CANCEL }
  | { type: typeof ENVELOPE_PERMISSION; requestId: string; allow: boolean };

/** promptCommand builds the envelope for a user message. */
export function promptCommand(text: string): AgentCommand {
  return { type: ENVELOPE_PROMPT, text };
}

/** cancelCommand asks the agent to stop the current turn. */
export function cancelCommand(): AgentCommand {
  return { type: ENVELOPE_CANCEL };
}

/** permissionCommand is the user's answer to a card. */
export function permissionCommand(requestId: string, allow: boolean): AgentCommand {
  return { type: ENVELOPE_PERMISSION, requestId, allow };
}

/** agentSocketURL is the bridge's WebSocket URL on the viewer's own origin. */
export function agentSocketURL(location: { protocol: string; host: string }): string {
  const scheme = location.protocol === "https:" ? "wss:" : "ws:";
  return `${scheme}//${location.host}${AGENT_WS_PATH}`;
}

/** fetchAgentState reads the bridge's posture: the one call an inert panel makes. */
export async function fetchAgentState(): Promise<AgentState> {
  return agentRequest(AGENT_STATE_PATH);
}

/** activateAgent dials the socket the user typed. The path is never remembered. */
export async function activateAgent(socket: string): Promise<AgentState> {
  return agentRequest(AGENT_ACTIVATE_PATH, { socket });
}

/** deactivateAgent closes the connection and returns the viewer to inert. */
export async function deactivateAgent(): Promise<AgentState> {
  return agentRequest(AGENT_DEACTIVATE_PATH, {});
}

/** agentRequest posts to an agent endpoint and reports the viewer's message on refusal. */
async function agentRequest(path: string, body?: unknown): Promise<AgentState> {
  const response = await fetch(path, {
    method: body === undefined ? "GET" : "POST",
    headers: body === undefined ? undefined : { "Content-Type": "application/json" },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  if (!response.ok) {
    const payload = (await response.json().catch(() => null)) as { error?: string } | null;
    throw new Error(payload?.error ?? `the viewer answered ${response.status}`);
  }
  return (await response.json()) as AgentState;
}

/** AgentConnection is one open conversation. */
export interface AgentConnection {
  send(command: AgentCommand): void;
  close(): void;
}

/**
 * connectAgent opens the bridge's WebSocket and hands every whole-thread state to
 * `onState`. There is no reconnect: the panel owns the connection's lifetime, so a
 * closed socket is reported once (`onClose`) and the panel decides what to do. The
 * browser side never reassembles chunks — every message is the whole thread — so a
 * state that arrives while the caller is busy is simply superseded by the next one.
 */
export function connectAgent(options: {
  onState: (envelope: AgentStateEnvelope) => void;
  onClose?: (reason: string) => void;
  url?: string;
}): AgentConnection {
  const url = options.url ?? agentSocketURL(window.location);
  const socket = new WebSocket(url);
  socket.addEventListener("message", (event: MessageEvent<string>) => {
    let envelope: AgentStateEnvelope;
    try {
      envelope = JSON.parse(event.data) as AgentStateEnvelope;
    } catch {
      // A message the wire does not define is dropped rather than fatal: the next
      // state is the whole thread, so nothing is lost by ignoring this one.
      return;
    }
    if (envelope.type === ENVELOPE_STATE) options.onState(envelope);
  });
  socket.addEventListener("close", (event: CloseEvent) => {
    options.onClose?.(event.reason || "the connection closed");
  });
  return {
    send(command: AgentCommand) {
      if (socket.readyState === WebSocket.OPEN) socket.send(JSON.stringify(command));
    },
    close() {
      socket.close();
    },
  };
}
